import React, { useState, useEffect } from 'react';
const API_BASE = 'http://localhost:5000/api';

function App() {
  const [token, setToken] = useState(localStorage.getItem('plateai_token') || '');
  const [currentUser, setCurrentUser] = useState(JSON.parse(localStorage.getItem('plateai_user') || 'null'));

  const [authMode, setAuthMode] = useState('signin');
  const [emailInput, setEmailInput] = useState('');
  const [passwordInput, setPasswordInput] = useState('');
  const [nameInput, setNameInput] = useState('');
  const [roleInput, setRoleInput] = useState('Admin');
  const [authError, setAuthError] = useState('');

  const [activeTab, setActiveTab] = useState('overview');

  // Role checks (supports both 'Admin' and 'Admin / Canteen manager')
  const isAdminView = currentUser?.role === 'Admin' || currentUser?.role === 'Admin / Canteen manager';

  const [overviewData, setOverviewData] = useState(null);
  const [forecastData, setForecastData] = useState({
    expectedAttendance: 438,
    day: 'Wednesday',
    mealType: 'Lunch',
    safetyBuffer: 15,
    temperature: 28,
    rainfall: 0,
    holiday: false,
    campusEvent: false,
    weatherContext: { temp: 28, condition: 'Demo clear weather', rainfall: '0 mm', humidity: '62%' }
  });

  const [forecastMessage, setForecastMessage] = useState('');

  const [mealsList, setMealsList] = useState([]);
  const [mealSearchQuery, setMealSearchQuery] = useState('');
  const [newMealName, setNewMealName] = useState('');
  const [newMealCategory, setNewMealCategory] = useState('Hot Entree');
  const [newMealPlanned, setNewMealPlanned] = useState(100);

  const [surplusList, setSurplusList] = useState([]);
  const [recipientsList, setRecipientsList] = useState([
    { id: 1, name: 'Hope Community Kitchen', contact: 'Sarah Jenkins', type: 'Shelter', activeRequests: 2, status: 'Connected' },
    { id: 2, name: 'CareFirst Food Bank', contact: 'Marcus Vance', type: 'Food Bank', activeRequests: 1, status: 'Connected' },
    { id: 3, name: 'Neighborhood Youth Center', contact: 'Elena Rostova', type: 'Community Centre', activeRequests: 3, status: 'Pending match' }
  ]);
  const [impactData, setImpactData] = useState({
    totalMealsSaved: 3420,
    co2AvertedKg: 5130,
    peopleFed: 1280,
    communityPartnersCount: 6
  });

  const handleLogin = async (e) => {
    e.preventDefault();
    setAuthError('');
    try {
      const res = await fetch(`${API_BASE}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: emailInput, password: passwordInput })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Login failed');
      setToken(data.token);
      setCurrentUser(data.user);
      localStorage.setItem('plateai_token', data.token);
      localStorage.setItem('plateai_user', JSON.stringify(data.user));
    } catch (err) {
      setAuthError(err.message);
    }
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    setAuthError('');
    try {
      const res = await fetch(`${API_BASE}/register`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: nameInput || 'Maya Sharma', email: emailInput, password: passwordInput, role: roleInput })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Registration failed');
      setToken(data.token);
      setCurrentUser(data.user);
      localStorage.setItem('plateai_token', data.token);
      localStorage.setItem('plateai_user', JSON.stringify(data.user));
    } catch (err) {
      setAuthError(err.message);
    }
  };

  const handleLogout = () => {
    setToken('');
    setCurrentUser(null);
    localStorage.removeItem('plateai_token');
    localStorage.removeItem('plateai_user');
  };

  // Fetch data globally for all authenticated users
  useEffect(() => {
    if (!token) return;
    fetch(`${API_BASE}/overview`, { headers: { Authorization: `Bearer ${token}` } })
      .then(res => res.json())
      .then(setOverviewData)
      .catch(() => {});

    fetch(`${API_BASE}/forecast`, { headers: { Authorization: `Bearer ${token}` } })
      .then(res => res.json())
      .then(data => { if (data) setForecastData(data); })
      .catch(() => {});

    fetch(`${API_BASE}/meals`, { headers: { Authorization: `Bearer ${token}` } })
      .then(res => res.json())
      .then(data => { if (Array.isArray(data)) setMealsList(data); })
      .catch(() => {});

    fetch(`${API_BASE}/surplus`, { headers: { Authorization: `Bearer ${token}` } })
      .then(res => res.json())
      .then(data => { if (Array.isArray(data)) setSurplusList(data); })
      .catch(() => {});
  }, [token]);

  // Handler to mark meal as served (Admin only)
  const handleMarkServed = async (mealId) => {
    try {
      const res = await fetch(`${API_BASE}/meals/${mealId}/serve`, {
        method: 'PATCH',
        headers: { Authorization: `Bearer ${token}` }
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to update meal status');
      if (data.success) {
        setMealsList(data.meals);
        setForecastMessage('Meal successfully marked as served.');
        setTimeout(() => setForecastMessage(''), 3000);
      }
    } catch (err) {
      setForecastMessage(err.message);
      setTimeout(() => setForecastMessage(''), 4000);
    }
  };

  // Handler to create a new meal plan (Admin only)
  const handleCreateMeal = async (e) => {
    e.preventDefault();
    if (!isAdminView) return;
    try {
      const res = await fetch(`${API_BASE}/meals`, {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}` 
        },
        body: JSON.stringify({
          name: newMealName,
          category: newMealCategory,
          planned: Number(newMealPlanned),
          service: 'Lunch',
          status: 'Planned'
        })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to create meal');
      if (data.success) {
        setMealsList(data.meals);
        setNewMealName('');
        setForecastMessage('New meal added successfully.');
        setTimeout(() => setForecastMessage(''), 3000);
      }
    } catch (err) {
      setForecastMessage(err.message);
      setTimeout(() => setForecastMessage(''), 4000);
    }
  };

  const filteredMeals = Array.isArray(mealsList) ? mealsList.filter(meal => 
    (meal.name || '').toLowerCase().includes(mealSearchQuery.toLowerCase()) ||
    (meal.category || '').toLowerCase().includes(mealSearchQuery.toLowerCase())
  ) : [];

  if (!token) {
    return (
      <div className="min-h-screen w-full flex flex-col lg:flex-row font-sans bg-white">
        <div className="lg:w-7/12 relative bg-[#142A1E] text-white p-12 flex flex-col justify-between overflow-hidden min-h-[400px]">
          <h1 className="text-5xl lg:text-7xl font-extrabold tracking-tight mb-6 leading-none relative z-10">Serve what matters.</h1>
        </div>
        <div className="lg:w-5/12 p-8 lg:p-16 flex flex-col justify-center bg-white">
          <div className="max-w-md w-full mx-auto">
            <h2 className="text-3xl font-extrabold text-gray-900 mb-2">Good to see you.</h2>
            <div className="flex bg-gray-100 p-1 rounded-xl mb-8">
              <button type="button" onClick={() => { setAuthMode('signin'); setAuthError(''); }} className={`flex-1 py-2.5 text-xs font-bold rounded-lg ${authMode === 'signin' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-500'}`}>Sign in</button>
              <button type="button" onClick={() => { setAuthMode('register'); setAuthError(''); }} className={`flex-1 py-2.5 text-xs font-bold rounded-lg ${authMode === 'register' ? 'bg-white shadow-sm text-gray-900' : 'text-gray-500'}`}>Register</button>
            </div>
            {authError && <div className="mb-4 p-3 bg-red-50 text-red-600 text-xs rounded-lg font-semibold">{authError}</div>}
            <form onSubmit={authMode === 'signin' ? handleLogin : handleRegister} className="space-y-4">
              {authMode === 'register' && (
                <div>
                  <label className="block text-xs font-bold text-gray-700 mb-1">Full Name</label>
                  <input type="text" value={nameInput} onChange={e => setNameInput(e.target.value)} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm" required />
                </div>
              )}
              <div>
                <label className="block text-xs font-bold text-gray-700 mb-1">Email</label>
                <input type="email" value={emailInput} onChange={e => setEmailInput(e.target.value)} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm" required />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-700 mb-1">Password</label>
                <input type="password" value={passwordInput} onChange={e => setPasswordInput(e.target.value)} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm" required />
              </div>
              {authMode === 'register' && (
                <div>
                  <label className="block text-xs font-bold text-gray-700 mb-1">Role</label>
                  <select value={roleInput} onChange={e => setRoleInput(e.target.value)} className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm bg-white">
                    <option value="Admin">Admin</option>
                    <option value="Recipient">Recipient</option>
                  </select>
                </div>
              )}
              <button type="submit" className="w-full py-3.5 bg-[#142A1E] text-white font-bold rounded-xl text-sm mt-2">{authMode === 'signin' ? 'Sign in' : 'Create account'}</button>
            </form>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-[#F4F6F4] text-gray-800 font-sans">
      <aside className="w-72 bg-[#142A1E] text-white flex flex-col justify-between p-6 shrink-0">
        <div>
          <div className="mb-8 pt-2">
            <p className="text-[10px] font-bold tracking-widest text-gray-400 uppercase mb-1">WORKSPACE</p>
            <p className="text-xl font-bold tracking-tight text-white">PlateAI</p>
          </div>
          <nav className="space-y-1">
            {['Overview', 'Demand forecast', 'Meals & attendance', 'Surplus food', 'Recipients', 'Impact analytics'].map((item) => {
              const id = item.toLowerCase().split(' ')[0];
              return (
                <button key={item} onClick={() => setActiveTab(id)} className={`w-full text-left px-4 py-3 rounded-xl text-sm font-semibold transition-colors ${activeTab === id ? 'bg-[#1E3B2C] text-white' : 'text-gray-400 hover:text-white'}`}>
                  {item}
                </button>
              );
            })}
          </nav>
        </div>

        <div className="pt-6 border-t border-[#1E3B2C]">
          <div className="flex items-center gap-3 mb-4">
            <div className="w-10 h-10 rounded-full bg-[#1A7B48] text-white font-bold flex items-center justify-center text-sm">
              {currentUser?.name ? currentUser.name.split(' ').map(n => n[0]).join('') : 'MS'}
            </div>
            <div>
              <p className="text-xs font-bold text-white">{currentUser?.name}</p>
              <p className="text-[11px] text-gray-400">{currentUser?.role}</p>
            </div>
          </div>
          <button onClick={handleLogout} className="flex items-center gap-2 text-xs text-gray-400 hover:text-white transition-colors"><span>←</span> Sign out</button>
        </div>
      </aside>

      <div className="flex-1 flex flex-col min-w-0">
        <header className="bg-[#F4F6F4] px-10 py-6 flex justify-between items-center">
          <p className="text-[11px] font-bold text-gray-400 uppercase tracking-widest">PLATEAI WORKSPACE</p>
          <div className="border border-gray-200 rounded-xl px-4 py-2 text-sm bg-white font-semibold text-gray-700 shadow-sm">
            Role: {currentUser?.role} {!isAdminView && '(Read-Only Mode)'}
          </div>
        </header>

        <main className="flex-1 px-10 pb-12 overflow-y-auto">
          {!isAdminView && (
            <div className="mb-6 p-4 bg-blue-50 text-blue-800 text-xs font-bold rounded-xl border border-blue-200 flex items-center justify-between">
              <span>ℹ️ Recipient View Active: You can inspect all overview metrics, shared meal plans, and surplus food data below. Modifications are restricted to Admins.</span>
            </div>
          )}

          {forecastMessage && (
            <div className="mb-6 p-4 bg-amber-50 text-amber-800 text-xs font-bold rounded-xl border border-amber-200 flex items-center justify-between">
              <span>{forecastMessage}</span>
            </div>
          )}

          {/* OVERVIEW TAB */}
          {activeTab === 'overview' && (
            <div className="space-y-6">
              <h2 className="text-xl font-extrabold text-gray-900">Overview Dashboard</h2>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100"><span className="text-xs text-gray-400 block mb-2">Expected demand</span><p className="text-2xl font-bold">{overviewData?.expectedDemand || '407 meals'}</p></div>
                <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100"><span className="text-xs text-gray-400 block mb-2">Recommended prep</span><p className="text-2xl font-bold">{overviewData?.recommendedPrep || '422 meals'}</p></div>
                <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100"><span className="text-xs text-gray-400 block mb-2">Actual consumption</span><p className="text-2xl font-bold">{overviewData?.actualConsumption || '410 meals'}</p></div>
                <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100"><span className="text-xs text-gray-400 block mb-2">Safe surplus</span><p className="text-2xl font-bold">{overviewData?.safeSurplus || '60 meals'}</p></div>
              </div>
            </div>
          )}

          {/* DEMAND FORECAST TAB */}
          {activeTab === 'demand' && (
            <div className="space-y-8">
              <h1 className="text-3xl font-extrabold tracking-tight text-gray-900">Demand Forecast</h1>
              <div className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100 space-y-6">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-xs font-bold text-gray-700 mb-1">Expected attendance</label>
                    <input type="number" value={forecastData.expectedAttendance} readOnly className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm bg-gray-50" />
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-gray-700 mb-1">Day</label>
                    <input type="text" value={forecastData.day} readOnly className="w-full px-4 py-3 border border-gray-200 rounded-xl text-sm bg-gray-50" />
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* MEALS & ATTENDANCE TAB */}
          {activeTab === 'meals' && (
            <div className="space-y-6">
              <div className="flex justify-between items-center">
                <h1 className="text-2xl font-extrabold text-gray-900">Meals & Attendance</h1>
              </div>

              {isAdminView && (
                <form onSubmit={handleCreateMeal} className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 flex gap-4 items-end">
                  <div className="flex-1">
                    <label className="block text-xs font-bold text-gray-700 mb-1">Meal Name</label>
                    <input type="text" value={newMealName} onChange={e => setNewMealName(e.target.value)} placeholder="e.g. Vegetarian Pasta" className="w-full px-3 py-2 border rounded-xl text-sm" required />
                  </div>
                  <div className="w-48">
                    <label className="block text-xs font-bold text-gray-700 mb-1">Category</label>
                    <select value={newMealCategory} onChange={e => setNewMealCategory(e.target.value)} className="w-full px-3 py-2 border rounded-xl text-sm bg-white">
                      <option value="Hot Entree">Hot Entree</option>
                      <option value="Side Dish">Side Dish</option>
                      <option value="Bakery">Bakery</option>
                    </select>
                  </div>
                  <div className="w-32">
                    <label className="block text-xs font-bold text-gray-700 mb-1">Planned</label>
                    <input type="number" value={newMealPlanned} onChange={e => setNewMealPlanned(e.target.value)} className="w-full px-3 py-2 border rounded-xl text-sm" required />
                  </div>
                  <button type="submit" className="px-5 py-2.5 bg-[#142A1E] text-white font-bold rounded-xl text-sm">Add Meal</button>
                </form>
              )}

              <input type="text" placeholder="Search meals..." value={mealSearchQuery} onChange={e => setMealSearchQuery(e.target.value)} className="w-full max-w-sm px-4 py-2 border border-gray-200 rounded-xl text-sm bg-white shadow-sm" />

              <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="border-b border-gray-100 text-[11px] font-bold text-gray-400 uppercase tracking-wider bg-gray-50/50">
                      <th className="py-3 px-6">Meal Name</th>
                      <th className="py-3 px-6">Category</th>
                      <th className="py-3 px-6">Planned</th>
                      <th className="py-3 px-6">Status</th>
                      <th className="py-3 px-6">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100 text-sm">
                    {filteredMeals.length === 0 ? (
                      <tr><td colSpan="5" className="text-center py-6 text-gray-400 text-xs">No meals found.</td></tr>
                    ) : (
                      filteredMeals.map(meal => (
                        <tr key={meal._id || meal.mealId} className="hover:bg-gray-50/50">
                          <td className="py-4 px-6 font-semibold text-gray-900">{meal.name}</td>
                          <td className="py-4 px-6 text-xs text-gray-600">{meal.category}</td>
                          <td className="py-4 px-6 font-bold text-gray-900">{meal.planned}</td>
                          <td className="py-4 px-6"><span className="px-2.5 py-1 rounded-full text-xs font-bold bg-emerald-50 text-[#1A7B48]">{meal.status || 'Planned'}</span></td>
                          <td className="py-4 px-6">
                            {isAdminView && meal.status !== 'Served' && (
                              <button onClick={() => handleMarkServed(meal.mealId)} className="px-3 py-1.5 bg-[#142A1E] text-white text-xs font-bold rounded-lg hover:bg-black transition-colors">
                                Mark Served
                              </button>
                            )}
                          </td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* SURPLUS FOOD TAB */}
          {activeTab === 'surplus' && (
            <div className="space-y-8">
              <h1 className="text-3xl font-extrabold tracking-tight text-gray-900">Surplus Food Register</h1>
              <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="border-b border-gray-100 text-[11px] font-bold text-gray-400 uppercase tracking-wider bg-gray-50/50">
                      <th className="py-3 px-6">Food</th>
                      <th className="py-3 px-6">Quantity</th>
                      <th className="py-3 px-6">Storage</th>
                      <th className="py-3 px-6">Safety state</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100 text-sm">
                    {surplusList.length === 0 ? (
                      <tr><td colSpan="4" className="text-center py-6 text-gray-400 text-xs">No surplus recorded yet.</td></tr>
                    ) : (
                      surplusList.map((item) => (
                        <tr key={item._id} className="hover:bg-gray-50/50">
                          <td className="py-4 px-6 font-semibold text-gray-900">{item.food}</td>
                          <td className="py-4 px-6 font-bold text-gray-900">{item.quantity}</td>
                          <td className="py-4 px-6 text-xs text-gray-600">{item.storage}</td>
                          <td className="py-4 px-6"><span className="px-3 py-1 rounded-full text-xs font-bold bg-emerald-50 text-[#1A7B48]">{item.safetyState}</span></td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* RECIPIENTS TAB */}
          {activeTab === 'recipients' && (
            <div className="space-y-6">
              <h1 className="text-2xl font-extrabold text-gray-900">Community Recipients & NGOs</h1>
              <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="border-b border-gray-100 text-[11px] font-bold text-gray-400 uppercase tracking-wider bg-gray-50/50">
                      <th className="py-3 px-6">Organization Name</th>
                      <th className="py-3 px-6">Contact Person</th>
                      <th className="py-3 px-6">Type</th>
                      <th className="py-3 px-6">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100 text-sm">
                    {recipientsList.map(rec => (
                      <tr key={rec.id} className="hover:bg-gray-50/50">
                        <td className="py-4 px-6 font-semibold text-gray-900">{rec.name}</td>
                        <td className="py-4 px-6 text-xs text-gray-600">{rec.contact}</td>
                        <td className="py-4 px-6 text-xs text-gray-600">{rec.type}</td>
                        <td className="py-4 px-6"><span className="px-2.5 py-1 rounded-full text-xs font-bold bg-emerald-50 text-[#1A7B48]">{rec.status}</span></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}

          {/* IMPACT ANALYTICS TAB */}
          {activeTab === 'impact' && (
            <div className="space-y-6">
              <h1 className="text-2xl font-extrabold text-gray-900">Impact Analytics & Sustainability</h1>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100"><span className="text-xs text-gray-400 block mb-2">Total Meals Saved</span><p className="text-3xl font-extrabold text-[#1A7B48]">{impactData.totalMealsSaved}</p></div>
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100"><span className="text-xs text-gray-400 block mb-2">CO2 Averted (kg)</span><p className="text-3xl font-extrabold text-[#142A1E]">{impactData.co2AvertedKg} kg</p></div>
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100"><span className="text-xs text-gray-400 block mb-2">People Fed</span><p className="text-3xl font-extrabold text-gray-900">{impactData.peopleFed}</p></div>
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100"><span className="text-xs text-gray-400 block mb-2">Partner Organizations</span><p className="text-3xl font-extrabold text-gray-900">{impactData.communityPartnersCount}</p></div>
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
}

export default App;
